def has_cycle(n, edges):
    adj = [[] for _ in range(n)]
    indegree = [0] * n

    for u, v in edges:
        adj[u].append(v)
        indegree[v] += 1

    queue = []
    for i in range(n):
        if indegree[i] == 0:
            queue.append(i)

    topo_order = []

    while queue:
        node = queue.pop(0)
        topo_order.append(node)

        for neighbor in adj[node]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                queue.append(neighbor)

    return topo_order if len(topo_order) == n else []
